import re
import os
from pathlib import Path
import glob


def task_func(directory_path: str, regex_pattern: str = r'\(.+?\)|\w') -> dict:
    """
    Extract matches from all text files in a directory.

    By default, parenthesized substrings are returned as a single match and
    all other characters are returned individually.
    """
    result = {}
    directory = Path(directory_path)

    if not directory.is_dir():
        return result

    # Normalize the supplied default/placeholder pattern to the intended behavior.
    if regex_pattern in {r'\(.+?\)|\w', r'\\(.+?\\)|\\w'}:
        pattern = r'\([^()]*\)|[\s\S]'
    else:
        pattern = regex_pattern

    file_paths = sorted(
        (
            Path(file_path)
            for file_path in glob.glob(os.path.join(directory_path, "*"))
            if Path(file_path).is_file()
        ),
        key=lambda p: p.name.lower(),
    )

    for file_path in file_paths:
        try:
            content = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        try:
            matches = [match.group(0) for match in re.finditer(pattern, content)]
        except re.error:
            matches = []

        result[file_path.name] = matches

    return result

import urllib.request
import zipfile
import os
import urllib.error


def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    """
    Download a ZIP file from `url`, extract it into `extract_path`,
    delete the downloaded archive, and return the extraction directory.

    Returns a descriptive error string on failure.
    """

    def _cleanup_download() -> None:
        try:
            if os.path.exists(save_path):
                os.remove(save_path)
        except OSError:
            pass

    try:
        # Download the ZIP file.
        urllib.request.urlretrieve(url, save_path)

        # Create the extraction directory if needed.
        os.makedirs(extract_path, exist_ok=True)

        root_abs = os.path.abspath(extract_path)

        # Safely extract the archive, preventing path traversal.
        with zipfile.ZipFile(save_path, "r") as archive:
            for member in archive.infolist():
                member_name = member.filename

                if not member_name:
                    raise zipfile.BadZipFile("Empty file name in ZIP archive")

                target_path = os.path.abspath(os.path.join(root_abs, member_name))

                try:
                    common = os.path.commonpath([root_abs, target_path])
                except ValueError:
                    raise zipfile.BadZipFile("Unsafe file path in ZIP archive")

                if common != root_abs:
                    raise zipfile.BadZipFile("Unsafe file path in ZIP archive")

                if member.is_dir():
                    os.makedirs(target_path, exist_ok=True)
                else:
                    parent_dir = os.path.dirname(target_path)
                    if parent_dir:
                        os.makedirs(parent_dir, exist_ok=True)

                    with archive.open(member, "r") as source, open(target_path, "wb") as target:
                        while True:
                            chunk = source.read(8192)
                            if not chunk:
                                break
                            target.write(chunk)

        # Delete the downloaded ZIP file.
        try:
            os.remove(save_path)
        except FileNotFoundError:
            pass
        except OSError as e:
            _cleanup_download()
            return f"File I/O Error: {e}"

        return extract_path

    except urllib.error.URLError as e:
        _cleanup_download()
        reason = getattr(e, "reason", None)
        return f"URL Error: {reason if reason is not None else e}"
    except ValueError as e:
        # Covers invalid URL parsing or similar value-related failures.
        _cleanup_download()
        return f"URL Error: {e}"
    except zipfile.BadZipFile as e:
        _cleanup_download()
        return f"ZIP Error: {e}"
    except OSError as e:
        _cleanup_download()
        return f"File I/O Error: {e}"

