import pandas as pd
import json
import os
import shutil

def task_func(path):
    path = os.fspath(path)

    if not os.path.isdir(path):
        return pd.DataFrame(columns=["Source"])

    processed_dir = os.path.join(path, "processed")
    os.makedirs(processed_dir, exist_ok=True)

    def _unique_destination(directory, filename):
        base, ext = os.path.splitext(filename)
        candidate = os.path.join(directory, filename)
        counter = 1
        while os.path.exists(candidate):
            candidate = os.path.join(directory, f"{base}_{counter}{ext}")
            counter += 1
        return candidate

    frames = []

    for filename in sorted(os.listdir(path)):
        file_path = os.path.join(path, filename)

        if not os.path.isfile(file_path):
            continue
        if not filename.lower().endswith(".json"):
            continue
        if os.path.abspath(file_path) == os.path.abspath(processed_dir):
            continue

        try:
            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            try:
                df = pd.read_json(file_path)
                if isinstance(df, pd.Series):
                    df = df.to_frame().T
            except Exception:
                continue
        else:
            if isinstance(data, dict):
                try:
                    df = pd.DataFrame(data)
                except Exception:
                    df = pd.DataFrame([data])
            elif isinstance(data, list):
                df = pd.DataFrame(data)
            else:
                df = pd.DataFrame({"value": [data]})

        if "Source" in df.columns:
            df = df.drop(columns=["Source"])
        df.insert(0, "Source", filename)

        frames.append(df)

        destination = _unique_destination(processed_dir, filename)
        shutil.move(file_path, destination)

    if frames:
        return pd.concat(frames, ignore_index=True, sort=False)

    return pd.DataFrame(columns=["Source"])

