SUPPORTED_EXTENSIONS = {".txt", ".docx", ".xlsx", ".csv"}


def _extract_text_from_text_file(path: Path) -> str:
    return path.read_text(encoding="utf-8-sig", errors="replace")


def _extract_text_from_docx(path: Path) -> str:
    document = docx.Document(str(path))
    parts = []

    for paragraph in document.paragraphs:
        text = paragraph.text.strip()
        if text:
            parts.append(text)

    for table in document.tables:
        for row in table.rows:
            row_parts = []
            for cell in row.cells:
                cell_text = cell.text.strip()
                if cell_text:
                    row_parts.append(cell_text)
            if row_parts:
                parts.append(" ".join(row_parts))

    return "\n".join(parts)


def _extract_text_from_xlsx(path: Path) -> str:
    parts = []
    workbook = pd.ExcelFile(path)

    for sheet_name in workbook.sheet_names:
        sheet = pd.read_excel(
            workbook,
            sheet_name=sheet_name,
            header=None,
            dtype=str,
            keep_default_na=False,
        )

        if sheet.empty:
            continue

        for row in sheet.itertuples(index=False, name=None):
            cells = []
            for cell in row:
                if cell is None:
                    continue
                cell_text = str(cell).strip()
                if cell_text:
                    cells.append(cell_text)
            if cells:
                parts.append(" ".join(cells))

    return "\n".join(parts)


def task_func(source_directory: str, target_directory: str) -> int:
    source_path = Path(os.fspath(source_directory))
    target_path = Path(os.fspath(target_directory))

    if not source_path.exists():
        raise FileNotFoundError(f"Source directory does not exist: {source_directory}")
    if not source_path.is_dir():
        raise NotADirectoryError(f"Source path is not a directory: {source_directory}")

    target_path.mkdir(parents=True, exist_ok=True)

    converted_count = 0
    source_files = sorted(
        (path for path in source_path.iterdir() if path.is_file()),
        key=lambda path: path.name.lower(),
    )

    for file_path in source_files:
        suffix = file_path.suffix.lower()
        if suffix not in SUPPORTED_EXTENSIONS:
            continue

        if suffix in {".txt", ".csv"}:
            text = _extract_text_from_text_file(file_path)
        elif suffix == ".docx":
            text = _extract_text_from_docx(file_path)
        elif suffix == ".xlsx":
            text = _extract_text_from_xlsx(file_path)
        else:
            continue

        output_file = target_path / f"{file_path.stem}.csv"
        pd.DataFrame({"Text": [text]}).to_csv(output_file, index=False)
        converted_count += 1

    return converted_count

import pytz
import numpy as np
from dateutil.parser import parse
import math
MOON_PHASES_YEARS = np.array([1987, 1994, 2001, 2008, 2015, 2022])

from datetime import datetime, timedelta

_SYNODIC_MONTH = 29.530588853  # Mean synodic month in days
_NEW_MOON_EPOCH = datetime(2000, 1, 6, 18, 14, tzinfo=pytz.UTC)


def _get_timezone(tz_value):
    """
    Accept either a timezone name string or a tzinfo-like object.
    """
    if hasattr(tz_value, "localize") and hasattr(tz_value, "utcoffset"):
        return tz_value
    return pytz.timezone(str(tz_value))


def _localize_or_convert(dt, zone):
    """
    Localize naive datetimes or convert aware datetimes to the requested zone.
    """
    if dt.tzinfo is not None:
        return dt.astimezone(zone)

    try:
        return zone.localize(dt, is_dst=None)
    except pytz.AmbiguousTimeError:
        return zone.localize(dt, is_dst=False)
    except pytz.NonExistentTimeError:
        # Move forward to the first valid moment in the local timeline.
        return zone.localize(dt + timedelta(hours=1), is_dst=False)


def _moon_illumination(dt_utc):
    """
    Return moon illumination in [0, 1], where 0 is new moon and 1 is full moon.
    """
    days_since_epoch = (dt_utc - _NEW_MOON_EPOCH).total_seconds() / 86400.0

    # Use the 7-year reference sequence as an anchor hint while keeping the
    # astronomical computation based on the actual instant in time.
    _reference_year = int(
        MOON_PHASES_YEARS[np.argmin(np.abs(MOON_PHASES_YEARS - dt_utc.year))]
    )

    lunar_age = days_since_epoch % _SYNODIC_MONTH
    phase_angle = 2.0 * math.pi * (lunar_age / _SYNODIC_MONTH)

    # Illumination fraction: 0 at new moon, 1 at full moon.
    illumination = (1.0 - math.cos(phase_angle)) / 2.0
    return max(0.0, min(1.0, float(illumination)))


def task_func(date_str, from_tz, to_tz):
    from_zone = _get_timezone(from_tz)
    to_zone = _get_timezone(to_tz)

    dt = parse(date_str)
    dt_from = _localize_or_convert(dt, from_zone)
    dt_to = dt_from.astimezone(to_zone)

    # Moon phase depends on absolute time; use UTC for the calculation.
    dt_utc = dt_to.astimezone(pytz.UTC)
    return _moon_illumination(dt_utc)

