def task_func(word_dict):
    """
    Count the frequency of each letter in the dictionary keys.

    Args:
        word_dict: A dictionary whose keys are words.

    Returns:
        dict: A dictionary mapping each letter to its frequency.
    """
    if not word_dict:
        return {}

    letter_counts = Counter(
        ch
        for word in word_dict
        for ch in str(word)
        if ch.isalpha()
    )
    return dict(letter_counts)

