from urllib.parse import urlparse

# Redefining the function in the current context
HEADERS = {
    'accept': 'text/json',
    'Content-Type': 'application/json'
}
def task_func(url, directory, metadata):
    if not isinstance(url, str) or not url.strip():
        raise TypeError("url is invalid")

    clean_url = url.strip()
    parsed_url = urlparse(clean_url)
    if parsed_url.scheme not in {"http", "https"} or not parsed_url.netloc:
        raise TypeError("url is invalid")

    if not os.path.isdir(directory):
        raise FileNotFoundError(directory)

    status_codes = []
    request_headers = {"accept": HEADERS["accept"]}

    for entry in sorted(os.listdir(directory)):
        file_path = os.path.join(directory, entry)
        if not os.path.isfile(file_path):
            continue

        with open(file_path, "rb") as file_obj:
            files = {"file": (entry, file_obj)}
            data = {"metadata": json.dumps(metadata)}
            try:
                response = requests.post(clean_url, headers=request_headers, files=files, data=data)
                status_codes.append(response.status_code)
            finally:
                time.sleep(1)

    return status_codes

from random import randint, seed
import pandas as pd

# Method
def task_func(goals, penalties, rng_seed=None):
    """
    Build a DataFrame with columns:
      - Team
      - Match Result

    `goals` and `penalties` can be scalars or iterable collections.
    If an element is a 2-item integer tuple/list, it is interpreted as
    an inclusive random range and sampled with randint.
    Penalties are converted into fines using a predefined cost.
    """
    PREDEFINED_FINE_COST = 100

    if rng_seed is not None:
        seed(rng_seed)

    def _to_list(value):
        if value is None:
            return []
        if isinstance(value, (str, bytes)):
            return [value]
        if hasattr(value, "tolist"):
            try:
                converted = value.tolist()
                return converted if isinstance(converted, list) else [converted]
            except Exception:
                pass
        if isinstance(value, (list, tuple)):
            return list(value)
        try:
            iter(value)
        except TypeError:
            return [value]
        return list(value)

    def _materialize(item):
        if (
            isinstance(item, (list, tuple))
            and len(item) == 2
            and all(isinstance(x, int) for x in item)
        ):
            low, high = item
            return randint(low, high)
        return item

    def _pad(values, size):
        if size <= 0:
            return []
        if not values:
            return [0] * size
        if len(values) >= size:
            return values[:size]
        return values + [values[-1]] * (size - len(values))

    goals_list = [_materialize(v) for v in _to_list(goals)]
    penalties_list = [_materialize(v) for v in _to_list(penalties)]

    n_teams = max(len(goals_list), len(penalties_list))
    if n_teams == 0:
        return pd.DataFrame(columns=["Team", "Match Result"])

    goals_list = _pad(goals_list, n_teams)
    penalties_list = _pad(penalties_list, n_teams)

    teams = [f"Team {i + 1}" for i in range(n_teams)]
    match_results = [
        f"Goals: {g}, Penalties: {p}, Fine: {p * PREDEFINED_FINE_COST}"
        for g, p in zip(goals_list, penalties_list)
    ]

    return pd.DataFrame({"Team": teams, "Match Result": match_results})

import json
from datetime import datetime
from decimal import Decimal


def task_func(my_obj, My_class=None):
    """
    Serialize an object to a JSON string, with support for datetime and Decimal.
    The My_class parameter is reserved for future use and is ignored.
    """

    def normalize(obj):
        if isinstance(obj, datetime):
            return obj.isoformat()
        if isinstance(obj, Decimal):
            # Preserve integers as ints; otherwise use float for JSON numeric output.
            return int(obj) if obj == obj.to_integral_value() else float(obj)
        if isinstance(obj, dict):
            return {normalize(key): normalize(value) for key, value in obj.items()}
        if isinstance(obj, (list, tuple, set, frozenset)):
            return [normalize(item) for item in obj]
        return obj

    return json.dumps(normalize(my_obj))

